import Foundation
import Metal
struct Case:Decodable{let n:Int;let q:Int;let dimension:Int;let phase_count:Int;let f0_hex:String;let basis_hex:[String]}
struct Input:Decodable{let schema:String;let cases:[Case]}
struct Row:Codable{let n:Int;let q:Int;let phases:Int;let rank_ok:Bool;let gpu_bad:Int;let cpu_equal:Bool;let host_ms:Double}
struct Report:Codable{let input_sha256:String;let source_sha256:String;let device:String;let phases:Int;let host_ms:Double;let rows:[Row];let status:String}
let metal=#"""
#include <metal_stdlib>
using namespace metal;
kernel void fwht(device const int*inputData[[buffer(0)]],device int*out[[buffer(1)]],constant uint&n[[buffer(2)]],uint3 tid3[[thread_position_in_threadgroup]],uint3 grp[[threadgroup_position_in_grid]]){threadgroup int a[256];uint x=tid3.x,p=grp.x;a[x]=inputData[p*n+x];threadgroup_barrier(mem_flags::mem_threadgroup);for(uint s=1;s<n;s<<=1){int l=a[x],r=a[x^s];threadgroup_barrier(mem_flags::mem_threadgroup);a[x]=(x&s)==0?l+r:r-l;threadgroup_barrier(mem_flags::mem_threadgroup);}out[p*n+x]=a[x];}
"""#
func die(_ s:String)->Never{FileHandle.standardError.write(Data((s+"\n").utf8));exit(2)}
func hex(_ s:String)->[UInt64]{let t=s.hasPrefix("0x") ? String(s.dropFirst(2)):s;guard t.count%16==0 else{die("hex length")};return stride(from:t.count,through:16,by:-16).map{UInt64(t[t.index(t.startIndex,offsetBy:$0-16)..<t.index(t.startIndex,offsetBy:$0)],radix:16)!}}
func xor(_ a:[UInt64],_ b:[UInt64])->[UInt64]{zip(a,b).map(^)}
func bit(_ a:[UInt64],_ i:Int)->Bool{((a[i/64]>>UInt64(i%64))&1)==1}
func rank(_ vv:[[UInt64]])->Int{var p=[Int:[UInt64]]();for var x in vv{while let k=(0..<x.count).reversed().first(where:{x[$0] != 0}){let h=k*64+63-x[k].leadingZeroBitCount;if let y=p[h]{x=xor(x,y)}else{p[h]=x;break}}};return p.count}
func cpu(_ sign:[Int64])->[Int64]{var a=sign,s=1;while s<a.count{var i=0;while i<a.count{for j in i..<(i+s){let l=a[j],r=a[j+s];a[j]=l+r;a[j+s]=l-r};i += 2*s};s *= 2};return a}
guard CommandLine.arguments.count==5 else{die("usage")};let url=URL(fileURLWithPath:CommandLine.arguments[1]),out=URL(fileURLWithPath:CommandLine.arguments[2]),ih=CommandLine.arguments[3],sh=CommandLine.arguments[4];let input:Input;do{input=try JSONDecoder().decode(Input.self,from:Data(contentsOf:url))}catch{die("decode \(error)")};guard input.schema=="a28-r018-quadratic-graph-cases-v1"&&input.cases.count==2 else{die("schema")};guard let dev=MTLCreateSystemDefaultDevice(),let queue=dev.makeCommandQueue()else{die("metal")};let lib:MTLLibrary;let pipe:MTLComputePipelineState;do{lib=try dev.makeLibrary(source:metal,options:nil);pipe=try dev.makeComputePipelineState(function:lib.makeFunction(name:"fwht")!)}catch{die("Metal \(error)")};let chunk=2048;var rows=[Row](),sum=0,ms=0.0,good=true
for c in input.cases{let N=1<<c.n,f=hex(c.f0_hex),b=c.basis_hex.map(hex),rk=rank(b)==c.dimension && c.phase_count==(1<<c.dimension) && f.count==N/64 && b.allSatisfy{$0.count==f.count};if !rk{good=false};var start=0,bad=0,eq=true,tm=0.0;while start<c.phase_count{let m=min(chunk,c.phase_count-start);var signs=[Int32]();signs.reserveCapacity(m*N);var refs=[[Int64]]();for phase in start..<(start+m){var z=f;for j in 0..<c.dimension where ((phase>>j)&1)==1{z=xor(z,b[j])};let s=(0..<N).map{bit(z,$0) ? Int64(-1):Int64(1)};signs += s.map(Int32.init);refs.append(cpu(s))};let ib=signs.withUnsafeBytes{dev.makeBuffer(bytes:$0.baseAddress!,length:$0.count,options:.storageModeShared)!},ob=dev.makeBuffer(length:m*N*4,options:.storageModeShared)!,cb=queue.makeCommandBuffer()!,ce=cb.makeComputeCommandEncoder()!;var nn=UInt32(N);ce.setComputePipelineState(pipe);ce.setBuffer(ib,offset:0,index:0);ce.setBuffer(ob,offset:0,index:1);ce.setBytes(&nn,length:4,index:2);ce.dispatchThreadgroups(MTLSize(width:m,height:1,depth:1),threadsPerThreadgroup:MTLSize(width:N,height:1,depth:1));ce.endEncoding();let t=DispatchTime.now().uptimeNanoseconds;cb.commit();cb.waitUntilCompleted();guard cb.status == .completed else{die("command")};tm += Double(DispatchTime.now().uptimeNanoseconds-t)/1e6;let p=ob.contents().bindMemory(to:Int32.self,capacity:m*N);for i in 0..<(m*N){if abs(Int(p[i])) != c.q{bad += 1};if Int64(p[i]) != refs[i/N][i%N]{eq=false}};start += m};if bad>0 || !eq{good=false};rows.append(Row(n:c.n,q:c.q,phases:c.phase_count,rank_ok:rk,gpu_bad:bad,cpu_equal:eq,host_ms:tm));sum += c.phase_count;ms += tm}
let r=Report(input_sha256:ih,source_sha256:sh,device:dev.name,phases:sum,host_ms:ms,rows:rows,status:good ? "passed":"failed");try! JSONEncoder().encode(r).write(to:out);print("status=\(r.status) phases=\(sum) host_ms=\(ms)");exit(good ? 0:1)
